export function cityProviderId(city: Pick<PhilippineCityOption, "cityName" | "provinceName" | "providerId">) {
  return city.providerId || `${slugify(city.provinceName)}:${slugify(city.cityName)}`;
}

function slugify(value: string) {
  return value
    .toLowerCase()
    .replace(/\bcity\b/g, "")
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "");
}
